// Turns trivia categories into four-option questions sorted by difficulty, for the games that ask them one at a time.
import { shuffle } from "../rng";
import type { TriviaCategory } from "./types";

export const TIERS = 4;
export type TierQuestion = { q: string; options: string[]; answer: string };

/**
 * One shuffled pool per tier (easiest first). A category only counts if it can fill every tier, because a clue's place
 * in the list is what says how hard it is.
 */
export function tierPools(categories: TriviaCategory[], seed: number): TierQuestion[][] {
  let s = seed;
  const tiers: TierQuestion[][] = [];
  for (let t = 0; t < TIERS; t++) {
    const pool: TierQuestion[] = [];
    for (const c of categories) {
      const clue = c.clues[t];
      if (!clue || c.clues.length < TIERS) continue;
      const [options, ns] = shuffle([clue.right, ...clue.wrong], s);
      s = ns;
      pool.push({ q: clue.q, options, answer: clue.right });
    }
    const [mixed, ns] = shuffle(pool, s);
    s = ns;
    tiers.push(mixed);
  }
  return tiers;
}
